mapper.select:
SELECT id, user_id, task_id, file_index, selected, declared_bytes, verified_bytes,
       state, created_at, updated_at, deleted
FROM magnet_v2_download_task_file
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0

mapper.update:
UPDATE magnet_v2_download_task_file
SET deleted = id, updated_at = CURRENT_TIMESTAMP(6)
WHERE id = #{id}
  AND user_id = #{userId}
  AND deleted = 0
